/* REG_SP_TXT: the name text id of species i = base + i - 1 (0xFFFF for 0 and out of range); es.txt keeps the gl.sp.* texts consecutive (contract 63.1) */
#if defined(TXT_GL_SP_EMBERCUB) && TXT_GL_SP_EMBERCUB != 0x801D
#error reg_sp_txt() is out of date: run python3 tools/regc.py
#endif
static inline uint16_t reg_sp_txt(unsigned i) { return (i - 1u) < 157u ? (uint16_t)(0x801Du + i - 1u) : (uint16_t)0xFFFF; }

/* REG_MV_TXT: the name text id of move i = base + i - 1 (0xFFFF for 0 and out of range); es.txt keeps the gl.mv.* texts consecutive (contract 63.1) */
#if defined(TXT_GL_MV_BUMP) && TXT_GL_MV_BUMP != 0x8408
#error reg_mv_txt() is out of date: run python3 tools/regc.py
#endif
static inline uint16_t reg_mv_txt(unsigned i) { return (i - 1u) < 166u ? (uint16_t)(0x8408u + i - 1u) : (uint16_t)0xFFFF; }

/* REG_IT_TXT: the name text id of item i = base + i - 1 (0xFFFF for 0 and out of range); es.txt keeps the gl.it.* texts consecutive (contract 63.1) */
#if defined(TXT_GL_IT_CRYSTAL) && TXT_GL_IT_CRYSTAL != 0x810A
#error reg_it_txt() is out of date: run python3 tools/regc.py
#endif
static inline uint16_t reg_it_txt(unsigned i) { return (i - 1u) < 122u ? (uint16_t)(0x810Au + i - 1u) : (uint16_t)0xFFFF; }

/* text id of the name of type n (type ids have no 'none' slot): arithmetic, see regc.py */
#if defined(TXT_GL_TY_NORMAL) && TXT_GL_TY_NORMAL != 0x800E
#error reg_ty_txt() is out of date: run python3 tools/regc.py
#endif
static inline uint16_t reg_ty_txt(unsigned n) { return n < 15u ? (uint16_t)(0x800Eu + n) : (uint16_t)0xFFFF; }
